import{_ as t,o,c as r,a2 as s}from"./chunks/framework.BEUshCVJ.js";const p=JSON.parse('{"title":"Practice mode","description":"","frontmatter":{},"headers":[],"relativePath":"guide/practice.md","filePath":"guide/practice.md","lastUpdated":1793314357000}'),a={name:"guide/practice.md"};function i(n,e,l,d,h,c){return o(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="practice-mode" tabindex="-1">Practice mode <a class="header-anchor" href="#practice-mode" aria-label="Permalink to &quot;Practice mode&quot;">​</a></h1><p>This page shows how to rehearse an interview or a meeting with MeetCue. It reads questions aloud, gives you hints exactly as in a real meeting, and gives you a review report afterwards.</p><div class="tip custom-block"><p class="custom-block-title">First time?</p><p><a href="/meetcue/guide/mock-interview">Mock interview</a> walks through a complete practice run step by step, with built-in sample interviews in English and Chinese.</p></div><h2 id="import-questions" tabindex="-1">Import questions <a class="header-anchor" href="#import-questions" aria-label="Permalink to &quot;Import questions&quot;">​</a></h2><p>Open <strong>Mock interview…</strong> from the tray menu, or click <strong>Try a mock interview</strong> on the panel. Pick a built-in sample interview, or choose your own file. Files are processed on your computer; only the text of questions and your answers is sent to the model.</p><table tabindex="0"><thead><tr><th>Type</th><th>Formats</th><th>Notes</th></tr></thead><tbody><tr><td>Meeting subtitles</td><td><code>.srt</code>, <code>.vtt</code>, <code>.txt</code></td><td>Speakers come from a <code>Name:</code> prefix or a VTT <code>&lt;v Name&gt;</code> tag. Choose which speaker is you.</td></tr><tr><td>Question list</td><td><code>.txt</code>, <code>.md</code>, <code>.csv</code></td><td>One question per line; a line starting with <code>#</code> starts a group. CSV columns are described in <a href="/meetcue/reference/file-formats">File formats</a>.</td></tr></tbody></table><p>Subtitle files without speaker names are labelled question or answer by the model; you check the result before starting.</p><p>After import, the preview table lets you edit, delete and reorder questions, shuffle them, or keep only a number of them.</p><p>The built-in samples are also in the repository under <a href="https://github.com/Amazingkenneth/meetcue/tree/HEAD/samples/practice" target="_blank" rel="noreferrer">samples/practice</a>, with matching job descriptions under <a href="https://github.com/Amazingkenneth/meetcue/tree/HEAD/samples/materials" target="_blank" rel="noreferrer">samples/materials</a>.</p><h2 id="the-asking-voice" tabindex="-1">The asking voice <a class="header-anchor" href="#the-asking-voice" aria-label="Permalink to &quot;The asking voice&quot;">​</a></h2><p>Questions are read by a Windows voice. In the mock interview window&#39;s first step, choose a voice for English and one for Chinese, press <strong>Try it</strong> to hear it, and set the reading speed. <strong>First voice Windows offers</strong> keeps MeetCue&#39;s own choice. Install more voices in Windows Settings › Time &amp; language › Speech.</p><h2 id="speech-to-text" tabindex="-1">Speech-to-text <a class="header-anchor" href="#speech-to-text" aria-label="Permalink to &quot;Speech-to-text&quot;">​</a></h2><p>Questions are always spoken aloud with the Windows speech voices, as in a real meeting. Two switches decide what is transcribed:</p><ul><li><strong>Speech-to-text for the questions</strong> (on by default): the spoken question is captured from system sound and recognised by your speech provider like a real meeting. The delay you see is the delay you&#39;ll get in a meeting. When off, the question&#39;s text goes straight to the hint model after a recognition delay drawn from your last latency probe. This saves the speech recognition cost for the other side. The model&#39;s own delay is real.</li><li><strong>Speech-to-text for my answers</strong> (on by default): your microphone is recognised for coverage ticks and the review. Turning it off as well removes all speech recognition cost, but also the ticks and some review figures.</li></ul><h2 id="pace-and-follow-ups" tabindex="-1">Pace and follow-ups <a class="header-anchor" href="#pace-and-follow-ups" aria-label="Permalink to &quot;Pace and follow-ups&quot;">​</a></h2><ul><li>For a question list, MeetCue asks a question and waits. If you don&#39;t start within 20 seconds, the panel shows a gentle reminder. A pause of 3 seconds, or <code>Ctrl+Alt+Enter</code>, ends your answer.</li><li>With follow-ups on, MeetCue sometimes (30% by default) asks a short follow-up question based on your answer.</li><li>For subtitles, other speakers&#39; lines play on the original timeline, with long gaps shortened to 2 seconds. Playback stops at your lines and waits for you; the original line becomes the reference answer in the review.</li><li><code>Ctrl+Alt+]</code> skips a question; <code>Ctrl+Alt+Space</code> pauses and resumes. <strong>Ask again</strong>, in the practice window and on the panel, reads the current question from the start and discards the answer you had begun.</li><li>If you start speaking while a question is still being read, playback stops. Only real speech counts: a cough, a filler word or a word misheard from the question itself doesn&#39;t cut it short. <strong>Stop reading when I start speaking</strong> turns this off.</li></ul><h2 id="hint-levels" tabindex="-1">Hint levels <a class="header-anchor" href="#hint-levels" aria-label="Permalink to &quot;Hint levels&quot;">​</a></h2><p>Choose a level before you start or change it during practice:</p><ol><li><strong>Full</strong>: the same as meeting mode.</li><li><strong>Keywords only</strong>: the bold keywords, without details or the sample answer.</li><li><strong>Delayed</strong>: hints appear a few seconds after the question ends.</li><li><strong>Off</strong>: hints only appear in the review.</li></ol><p>Step down one level at a time until you can answer without hints.</p><h2 id="review-report" tabindex="-1">Review report <a class="header-anchor" href="#review-report" aria-label="Permalink to &quot;Review report {#review-report}&quot;">​</a></h2><p>When you finish, the review shows for each question and for the whole session:</p><table tabindex="0"><thead><tr><th>Figure</th><th>Meaning</th></tr></thead><tbody><tr><td>Time to start</td><td>From the end of the question to your first recognised word</td></tr><tr><td>Answer length</td><td>From your first word to the end of your answer</td></tr><tr><td>Coverage</td><td>Talking points ticked off out of all points</td></tr><tr><td>Filler words</td><td>&quot;um&quot;, &quot;uh&quot;, &quot;like&quot;, &quot;you know&quot;, and 嗯、啊、那个、就是、然后 for Chinese; editable in settings</td></tr><tr><td>Pace</td><td>Words per minute (characters per minute for Chinese)</td></tr><tr><td>Feedback</td><td>With a reference answer, three short notes: what you missed, what to phrase better, what went well</td></tr></tbody></table><p>Export the report as Markdown. Past sessions are kept in the <code>practice</code> folder next to your settings, and the review shows your trend over time.</p>',24)])])}const m=t(a,[["render",i]]);export{p as __pageData,m as default};
